void __stdcall WeatherEffects() {
    // Static local variables (originally global data)
    static BOOL WEATHER_bCanMud;
    static BOOL WEATHER_bCanRain;

    bool bMudResult;
    D2RoomStrc* pRoom;
    eD2LevelId eLevel;
    D2UnitStrc* pPlayer;
    pPlayer = UNIT::Player::GetPlayerUnit_Net();
    BOOL bCanRain;
    bCanRain = 0;
    BOOL bCanMud;
    bCanMud = 0;
    if (pPlayer) {
      bool bRainResult;
      pRoom = D2Common::Units::UNITS_GetRoom(pPlayer);
      eLevel = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
      bRainResult = D2Common::DATATBLS::LvlTbls::LEVEL_CanHaveRain(eLevel);
      bCanRain = (BOOL)bRainResult;
      bMudResult = D2Common::DATATBLS::LvlTbls::LEVEL_CanHaveMud(eLevel);
      bCanMud = (BOOL)bMudResult;
      if (bCanRain) {
        goto clear_mud_and_update;
      }
    }
    if (WEATHER_bCanRain) {
      if (pEnvironmentParticles->nUsedCount) {
        Fog::Src::DataArrays::FOG_InitDataArray(pEnvironmentParticles);
      }
      if (pEnvironmentSplashes->nUsedCount) {
        Fog::Src::DataArrays::FOG_InitDataArray(pEnvironmentSplashes);
      }
    }

    clear_mud_and_update:
    if (!bCanMud && WEATHER_bCanMud && pEnvironmentBubbles->nUsedCount) {
      Fog::Src::DataArrays::FOG_InitDataArray(pEnvironmentBubbles);
    }
    WEATHER_bCanMud = bCanMud;
    WEATHER_bCanRain = bCanRain;
    uint32_t nRecordingIndex = GAME::Game::gnRecordingIndex();
    pPlayer = UNIT::Player::GetPlayerUnit_UI();
    if (!pPlayer) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x547);
      exit(-1);
    }

    D2SeedStrc* pSeed = &pPlayer->sSeed;
    if ((uint32_t)gnWeatherFrameIndex >= nRecordingIndex) {
      return;
    }

    gnWeatherFrameIndex = nRecordingIndex;
    if (!bCanRain) {
      gnWeatherTransitionInitialized = 0;
    } else {
      if (pEnvironmentParticles->nUsedCount) {
        WEATHER_UpdateParticles(pSeed);
      }

      WEATHER_UpdateSplashes();
      WEATHER_UpdateTransition(pSeed);
      WEATHER_UpdateParticleCount(pSeed);
    }
    if (!bCanMud) {
      return;
    }

    WEATHER_UpdateBubbles();
}

